"""Selected outputs, truthful attribution and the shared History/README publisher."""
import json,shutil,uuid
from datetime import datetime,timezone
from pathlib import Path
from ...artifacts import digest
from ....finishing.package_catalog import FileRecord,VariantRecord,build_catalog
from ....finishing.package_archive import publish_archive

DIRECTORIES={
    'splat':('Splat/','Detailed Gaussian splat generated by Idol. This is a point-based visual asset, not a polygon mesh.'),
    'raw':('Original_Mesh/','Original mesh extracted from the Idol splat before optional refinement or repair.'),
    'master':('Clean_Master/','Welded, closed high-detail companion geometry after optional Hi3D refinement and native cleanup.'),
    'companion':('Companion/','Simplified closed geometry for use alongside the visual splat; collision behavior requires engine-specific validation.'),
    'master_presentation':('Presentation/','A presentation copy with crease-aware normals. Coincident vertex splits serve shading.'),
    'companion_presentation':('Presentation/','A presentation copy with crease-aware normals. Coincident vertex splits serve shading.'),
    'orbit':('Preview/','Rendered orbit preview of the original splat.'),
    'master_preview':('Preview/','Untextured view of the clean master.'),'companion_preview':('Preview/','Untextured view of the simplified companion.')}
PACK=Path(__file__).resolve().parents[3]

def build(service,r):
    c=r['config'];ident=uuid.uuid4().hex;target=service.output_root/'foundry-splat'/r['id']/('package-'+ident);target.mkdir(parents=True)
    files=[];variants=[];selections=c['outputs']
    for role,(directory,description) in DIRECTORIES.items():
        selected=selections['presentation'] if role.endswith('_presentation') else selections['previews'] if role.endswith('_preview') else selections.get(role,False)
        if not selected:continue
        if role not in r['artifacts']:raise ValueError('Selected output is missing: '+role.replace('_',' '))
        service.check(r);source=service.artifact_path(r,role);relative=directory+role+source.suffix
        dest=target/relative;dest.parent.mkdir(exist_ok=True);shutil.copy2(source,dest)
        variant_id=directory.strip('/').lower()
        files.append(FileRecord(relative,'geometry' if source.suffix in ('.glb','.spz') else 'preview',variant_id,description,source.suffix.lstrip('.'),'preview' if role.endswith('_preview') else role))
        quality=r.get('quality',{}).get(role,{})
        if quality.get('sha256') and quality['sha256']!=digest(source):raise ValueError('Geometry changed after its audit: '+role)
        variant=next((v for v in variants if v.directory==directory),None)
        if variant:variant.file_paths.append(relative)
        else:
            validations=[dict(name='Exported geometry audit',status='pass' if quality['passed'] else 'fail',note='Topology, finite coordinates, duplicate faces and self-intersections checked on this saved file.')] if quality else []
            variants.append(VariantRecord(variant_id,directory,description,file_paths=[relative],measurements={'geometry':quality} if quality else {},validations=validations,
                limitations=['No UV/PBR, rigging, exact hidden-surface recovery, physical print or game-engine collision certification is implied.']))
    metadata=target/'Metadata';metadata.mkdir()
    model_catalog=json.loads((PACK/'models.lock.json').read_text(encoding='utf-8'))['models']
    production=dict(method='splat-solid/v1',workflow_title='Splat & Solid · Idol',settings=c,reference_sha256=r['source_sha256'],stages=r['completed'],quality=r.get('quality',{}),
        models={key:model_catalog[key] for key in ('idol','idol_dino','idol_decoder','idol_image_vae','birefnet')})
    # Paths in the public production record are package relative; no private runtime locations.
    (metadata/'generation.json').write_text(json.dumps(production,indent=2),encoding='utf-8')
    files.extend([FileRecord('Metadata/generation.json','metadata',None,'Selected workflow settings, completed stages and geometry checks.','json','provenance'),
                  FileRecord('Metadata/manifest.json','metadata',None,'Included files, checksums, measurements and upstream resources.','json','catalog')])
    pack=PACK
    registry=json.loads((pack/'finishing/package_resources.json').read_text(encoding='utf-8'))
    keys=['idol','comfyui','idol_dino','flux_vae','birefnet']
    if r['completed'].get('cleanup'):keys.append('pymeshlab')
    if c['refine'] and r['completed'].get('refinement'):keys.append('hi3d')
    resources=[registry[key] for key in keys]
    for resource in resources:
        for name in resource.get('notices',[]):
            relative='Licenses/'+name
            if any(f.path==relative for f in files):continue
            source=pack/'licenses/pipeline'/name;destination=target/relative;destination.parent.mkdir(exist_ok=True);shutil.copy2(source,destination)
            files.append(FileRecord(relative,'license',None,resource['name']+' retained license or notice.',source.suffix.lstrip('.'),'notice'))
    from ... import VERSION
    catalog=build_catalog(files,variants,resources,dict(name='Mumblebox 3D Asset Foundry',description='A curated toolbox of model-powered creative workflows.',github_url='https://github.com/mumblebox-gpt/mumblebox-foundry'),dict(asset_name=c['name'],export_id=ident,created_utc=datetime.now(timezone.utc).isoformat(),workflow_version=VERSION,production=production))
    archive=publish_archive(catalog,target,target.with_suffix('.zip'),lambda:service.check(r));history=service.library.import_package(archive)
    return dict(path=archive.relative_to(service.output_root).as_posix(),history_id=history['id'],bytes=archive.stat().st_size,sha256=digest(archive),zip_selected=selections['zip'])
